import{_ as n,C as o,o as a,c as d,a2 as e,E as s}from"./chunks/framework.BSaF8iZ6.js";const f=JSON.parse('{"title":"Returns (RMA)","description":"","frontmatter":{},"headers":[],"relativePath":"orders/return-merchandise-authorization.md","filePath":"orders/return-merchandise-authorization.md","lastUpdated":1789411447000}'),i={name:"orders/return-merchandise-authorization.md"};function u(l,t,h,g,c,p){const r=o("ImagePopup");return a(),d("div",null,[t[0]||(t[0]=e('<h1 id="returns-rma" tabindex="-1">Returns (RMA) <a class="header-anchor" href="#returns-rma" aria-label="Permalink to &quot;Returns (RMA)&quot;">​</a></h1><div class="page-roles"><span class="role role--customer">Customer</span><span class="role role--seller">Seller</span><span class="role role--admin">Admin</span></div><p>Returns use the store&#39;s RMA (return merchandise authorization) system. When a customer asks to return a product, the request goes to the seller who sold it. The seller talks to the customer and moves the request along, and the admin can see and act on every return.</p><h2 id="before-returns-can-be-requested" tabindex="-1">Before returns can be requested <a class="header-anchor" href="#before-returns-can-be-requested" aria-label="Permalink to &quot;Before returns can be requested&quot;">​</a></h2><ul><li>The store sets the return window, the return policy, the file types customers can attach and the product types that can be returned in <strong>Configure &gt;&gt; Sales &gt;&gt; RMA</strong>. See <a href="https://docs.bagisto.com/configure/rma" target="_blank" rel="noreferrer">RMA settings</a> in the Bagisto User Guide.</li><li>Sellers choose whether each product can be returned on the product&#39;s <strong>RMA</strong> step, with <strong>Allow RMA</strong> and a return rule. See <a href="./../catalog/product-management">Product Management</a>. The setting applies to orders placed after it is switched on, so switch it on before you start selling.</li></ul><h2 id="how-a-customer-asks-for-a-return" tabindex="-1">How a customer asks for a return <a class="header-anchor" href="#how-a-customer-asks-for-a-return" aria-label="Permalink to &quot;How a customer asks for a return&quot;">​</a></h2><p>Customers go to <strong>RMA</strong> in their account and create a request for one product at a time. A product can be returned once it is invoiced, and cancelled while it isn&#39;t invoiced yet. Customers choose what they want, the reason, the quantity and the package condition, can add details and photos, and must accept the return policy. See <a href="https://docs.bagisto.com/orders/rma" target="_blank" rel="noreferrer">RMA</a> in the Bagisto User Guide.</p><p>Sellers aren&#39;t emailed about new returns, so check <strong>Sales &gt;&gt; RMA</strong> regularly.</p><h2 id="your-return-requests" tabindex="-1">Your return requests <a class="header-anchor" href="#your-return-requests" aria-label="Permalink to &quot;Your return requests&quot;">​</a></h2><p>Go to <strong>Sales &gt;&gt; RMA</strong> in the Seller Panel.</p>',10)),s(r,{src:"/images/return-merchandise-authorization/rma-list.png",alt:"The seller's return requests"}),t[1]||(t[1]=e('<p>Each request shows the <strong>RMA ID</strong>, the <strong>Order ID</strong>, the <strong>Customer Name</strong>, the <strong>RMA Status</strong>, whether it was a <strong>Guest</strong> order, the <strong>Order Status</strong> (<strong>Delivered</strong>, <strong>Undelivered</strong>, <strong>Canceled</strong> or <strong>Closed</strong>) and the <strong>Date</strong>.</p><h2 id="handle-a-return" tabindex="-1">Handle a return <a class="header-anchor" href="#handle-a-return" aria-label="Permalink to &quot;Handle a return&quot;">​</a></h2><ol><li>Go to <strong>Sales &gt;&gt; RMA</strong>.</li><li>Click the view icon on the request.</li></ol>',3)),s(r,{src:"/images/return-merchandise-authorization/rma-status.png",alt:"A return request with its status, items and conversation"}),t[2]||(t[2]=e('<p>The page shows:</p><ul><li><strong>General</strong> — the date, package condition, the customer&#39;s information and photos;</li><li><strong>Items</strong> — the product, its price, the return and order quantities, what the customer wants and why;</li><li><strong>Conversation</strong> — messages between you and the customer;</li><li>the <strong>Status</strong>, the <strong>Order Details</strong> and the <strong>Customer Details</strong>.</li></ul><h3 id="reply-to-the-customer" tabindex="-1">Reply to the customer <a class="header-anchor" href="#reply-to-the-customer" aria-label="Permalink to &quot;Reply to the customer&quot;">​</a></h3><ol><li>Under <strong>Conversation</strong>, type your message.</li><li>To add a file, click <strong>Attachments</strong>. You can attach PDF, JPG or PNG files up to 2 MB.</li><li>Click <strong>Send Message</strong>.</li></ol><p>The customer receives a <strong>New RMA Message Received</strong> email. When the customer replies, the reply appears in the conversation; the store admin is emailed about it, not you.</p><h3 id="update-the-status" tabindex="-1">Update the status <a class="header-anchor" href="#update-the-status" aria-label="Permalink to &quot;Update the status&quot;">​</a></h3><ol><li>Choose the next status under <strong>Update Status</strong>.</li><li>Click <strong>Save Changes</strong>.</li></ol><p>The customer sees the new status on the return, with a note about the change in the conversation.</p><table tabindex="0"><thead><tr><th>From</th><th>You can choose</th></tr></thead><tbody><tr><td><strong>Pending Review</strong></td><td><strong>Approved</strong> or <strong>Request Declined</strong></td></tr><tr><td>An approved return</td><td><strong>Awaiting Return</strong>, <strong>Return In Transit</strong>, <strong>Refunded</strong> or <strong>Request Canceled</strong></td></tr><tr><td>An approved cancellation</td><td><strong>Awaiting Return</strong>, <strong>Item Canceled</strong> or <strong>Request Canceled</strong></td></tr></tbody></table><p>After <strong>Pending Review</strong>, active statuses the store adds itself also appear. Choosing <strong>Item Canceled</strong> cancels the product&#39;s quantity on the order.</p><div class="warning custom-block"><p class="custom-block-title">Refunds</p><p>Sellers can&#39;t issue refunds. Choosing <strong>Refunded</strong> in the Seller Panel doesn&#39;t refund the customer, and it hides the admin&#39;s refund option for that return. Leave the refund to the store admin, as described below.</p></div><p><strong>Update Status</strong> is no longer shown once the request is <strong>Refunded</strong>, <strong>Solved</strong>, <strong>Request Declined</strong>, <strong>Item Canceled</strong> or <strong>Request Canceled</strong>, or when the order is canceled or closed.</p><p>While a quantity is in a return request, whatever the request&#39;s status, it can&#39;t be shipped.</p><h2 id="return-statuses" tabindex="-1">Return statuses <a class="header-anchor" href="#return-statuses" aria-label="Permalink to &quot;Return statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>What it means</th></tr></thead><tbody><tr><td><strong>Pending Review</strong></td><td>The customer has asked for a return.</td></tr><tr><td><strong>Approved</strong></td><td>The return is accepted.</td></tr><tr><td><strong>Awaiting Return</strong></td><td>Waiting for the customer to send the product back.</td></tr><tr><td><strong>Return In Transit</strong></td><td>The product is on its way back.</td></tr><tr><td><strong>Refunded</strong></td><td>The request is marked as refunded.</td></tr><tr><td><strong>Solved</strong></td><td>The customer closed the request.</td></tr><tr><td><strong>Request Declined</strong></td><td>The return was refused.</td></tr><tr><td><strong>Item Canceled</strong></td><td>The product was cancelled on the order.</td></tr><tr><td><strong>Request Canceled</strong></td><td>The request was withdrawn.</td></tr></tbody></table><h2 id="for-the-admin" tabindex="-1">For the admin <a class="header-anchor" href="#for-the-admin" aria-label="Permalink to &quot;For the admin&quot;">​</a></h2><p>Go to <strong>Marketplace &gt;&gt; Sales &gt;&gt; RMA</strong> to see every return that includes a seller&#39;s product, with the <strong>Seller</strong> and <strong>Shop</strong>.</p>',17)),s(r,{src:"/images/return-merchandise-authorization/admin-rma.png",alt:"Seller returns in the admin panel"}),t[3]||(t[3]=e('<p>Click the view icon to open the return. There you can message the customer and seller, and change the status. When you change the status, the customer receives a <strong>Status Updated!</strong> email.</p><p>To refund the customer, use <strong>Refund Item</strong> or <strong>Cancel Item</strong> under <strong>Order Actions</strong>. They are available while the return is <strong>Approved</strong>, <strong>Awaiting Return</strong> or <strong>Return In Transit</strong>.</p><p>Return reasons, rules, statuses and custom fields are managed under <strong>Sales &gt;&gt; RMA</strong> in the admin panel.</p><h2 id="permissions" tabindex="-1">Permissions <a class="header-anchor" href="#permissions" aria-label="Permalink to &quot;Permissions&quot;">​</a></h2><ul><li>Team members need <strong>RMA</strong> with <strong>View</strong> to open and update returns.</li><li>Admins need <strong>Marketplace &gt;&gt; Sales &gt;&gt; RMA</strong> with <strong>View</strong> to see the list, and <strong>Sales &gt;&gt; RMA &gt;&gt; Requests</strong> to open, message and update a return.</li></ul>',5))])}const R=n(i,[["render",u]]);export{f as __pageData,R as default};
